-- Functions below resolve names with the search_path in effect now: the schemas that exist, temporary schema last
DO $sp$
DECLARE v_path text; v_bad text; f record;
BEGIN
  SELECT pg_catalog.string_agg(pg_catalog.format('%I (%s)', pw.schema, pw.who), ', ') INTO v_bad FROM (SELECT n.nspname::text AS schema, w.who
FROM pg_catalog.unnest(pg_catalog.current_schemas(false)) s(name) JOIN pg_catalog.pg_namespace n ON n.nspname = s.name,
LATERAL (SELECT CASE WHEN EXISTS (SELECT 1 FROM pg_catalog.aclexplode(n.nspacl) a
                                  WHERE a.grantee = 0 AND a.privilege_type = 'CREATE') THEN 'PUBLIC'
                ELSE (SELECT pg_catalog.string_agg(ro.rolname::text, ', ' ORDER BY ro.rolname) FROM pg_catalog.pg_roles ro
                      WHERE pg_catalog.has_schema_privilege(ro.oid, n.oid, 'CREATE') AND NOT ro.rolsuper
                        AND ro.rolname <> 'pg_database_owner' AND NOT pg_catalog.pg_has_role(ro.oid, CURRENT_USER, 'MEMBER')
                        AND NOT pg_catalog.pg_has_role(ro.oid, (SELECT d.datdba FROM pg_catalog.pg_database d
                                                               WHERE d.datname = pg_catalog.current_database()), 'MEMBER'))
                END AS who) w
-- a temporary schema is the session's own, and never searched for functions or operators
WHERE w.who IS NOT NULL AND n.nspname !~ '^pg_(toast_)?temp_') pw;
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION 'the search path has schemas that roles other than the owner may create objects in: % [AZ612]', v_bad
      USING HINT = 'rowstile''s functions that run as the owner resolve names on this path, so a function made there could run as the owner: revoke CREATE on those schemas, or apply with a search path without them';
  END IF;
  SELECT pg_catalog.string_agg(pg_catalog.quote_ident(s.name), ', ' ORDER BY s.i) INTO v_path
  FROM pg_catalog.unnest(pg_catalog.current_schemas(false)) WITH ORDINALITY s(name, i)
  WHERE s.name::text !~ '^pg_temp_';
  PERFORM pg_catalog.set_config('search_path', pg_catalog.concat_ws(', ', v_path, 'pg_temp'), true);
  -- functions made before (a migration keeps those it doesn't change) take the same path
  FOR f IN SELECT p.oid::regprocedure AS fn FROM pg_catalog.pg_proc p
           WHERE p.pronamespace IN (SELECT n.oid FROM pg_catalog.pg_namespace n WHERE n.nspname IN ('authz', 'authz_gen', 'authz_int'))
             AND EXISTS (SELECT 1 FROM pg_catalog.unnest(p.proconfig) c
                         WHERE c ^@ 'search_path=' AND c <> 'search_path=pg_catalog, pg_temp'
                           AND c <> 'search_path=' || pg_catalog.current_setting('search_path')) LOOP
    EXECUTE pg_catalog.format('ALTER FUNCTION %s SET search_path FROM CURRENT', f.fn);
  END LOOP;
END $sp$;

-- When the signature doesn't match: true for the owner's and superusers' sessions, else an error saying why
CREATE OR REPLACE FUNCTION authz_int.session_refused() RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_sig text := coalesce(current_setting('authz.session', true), '');
BEGIN
  -- the policy's owner and superusers say who is signed in by setting it (psql, migrations, tests)
  IF pg_has_role(session_user, (SELECT nspowner FROM pg_namespace WHERE nspname = 'authz_int'), 'MEMBER') THEN
    RETURN true;
  END IF;
  IF v_sig <> '' THEN
    RAISE EXCEPTION 'who is signed in was changed after signing in' USING ERRCODE = 'invalid_authorization_specification',
      HINT = 'say who is signed in with authz.act_as(), never by setting authz.user_id or the other authz settings '
             '(rowstile help AZ702)';
  ELSIF coalesce(current_setting('authz.user_id', true), '') <> '' THEN
    RAISE EXCEPTION 'authz.user_id was set directly, so it is not believed' USING ERRCODE = 'invalid_authorization_specification',
      HINT = 'sign in with SELECT authz.act_as(''user'', ''42''), authz.login_key() or authz.login_jwt() (rowstile help AZ702)';
  END IF;
  RAISE EXCEPTION 'nobody signed in in this transaction' USING ERRCODE = 'invalid_authorization_specification',
    HINT = 'start each transaction with SELECT authz.act_as(''user'', ''42''), or authz.act_as(NULL, NULL) for nobody '
           '(or authz.login_key() / authz.login_jwt()) (rowstile help AZ701)';
END $f$;

CREATE OR REPLACE FUNCTION authz_int.check_writable() RETURNS void
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  IF NOT authz_int.writable() THEN
    RAISE EXCEPTION 'this session is read-only (viewing as someone else, or a read-only token)'
      USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ704';
  END IF;
END $f$;

-- Read the feed from a position: SELECT * FROM authz.changes_since(0)  (administrators, sync jobs).
-- A reader behind what authz.trim_changes() removed gets an error: it must read everything again.
CREATE OR REPLACE FUNCTION authz.changes_since(p_pos bigint, p_limit int DEFAULT 1000) RETURNS SETOF authz.changes
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_to bigint := (SELECT s.value::bigint FROM authz.settings s WHERE s.key = 'changes_trimmed_to');
BEGIN
  IF p_pos < v_to THEN
    RAISE EXCEPTION 'the change feed up to position % was trimmed: read everything again, then follow from there', v_to
      USING ERRCODE = 'object_not_in_prerequisite_state', HINT = 'rowstile help AZ712';
  END IF;
  RETURN QUERY SELECT * FROM authz.changes WHERE pos > p_pos ORDER BY pos LIMIT p_limit;
END $f$;

-- The audit trail: entries older than p_keep (no default: how long to keep it is a compliance
-- decision). The trim itself is recorded in the audit trail.
CREATE OR REPLACE FUNCTION authz.trim_audit(p_keep interval) RETURNS bigint
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_before timestamptz; n bigint;
BEGIN
  IF p_keep IS NULL OR p_keep < interval '0' THEN
    RAISE EXCEPTION 'say how long to keep the audit trail, e.g. authz.trim_audit(interval ''2 years'')' USING HINT = 'rowstile help AZ710';
  END IF;
  v_before := now() - p_keep;
  -- the one way past the trigger is DDL, as the owner, here: nothing a session can set lets a DELETE through
  -- (ALTER TABLE takes an exclusive lock on the trail until the transaction ends)
  ALTER TABLE authz.audit DISABLE TRIGGER authz_audit_append_only;
  DELETE FROM authz.audit a WHERE a.at < v_before;
  GET DIAGNOSTICS n = ROW_COUNT;
  ALTER TABLE authz.audit ENABLE TRIGGER authz_audit_append_only;
  INSERT INTO authz.audit (db_role, user_id, action, detail)
  VALUES (authz_int.caller_role(), authz_int.actor(), 'trim_audit',
          jsonb_build_object('before', v_before, 'rows', n));
  RETURN n;
END $f$;

-- The audit trail only grows, except through authz.trim_audit()
CREATE OR REPLACE FUNCTION authz_int.audit_is_append_only() RETURNS trigger
LANGUAGE plpgsql AS $f$
BEGIN
  RAISE EXCEPTION 'the audit trail cannot be changed' USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ711';
END $f$;

CREATE OR REPLACE FUNCTION authz_gen."ms.users:update:refuse"(p_row "ms"."users") RETURNS boolean
LANGUAGE plpgsql VOLATILE SET search_path FROM CURRENT AS $f$
DECLARE v_lines text; v_who text := CASE WHEN coalesce(current_setting('authz.user_id', true), '') = '' THEN 'someone not signed in'
  ELSE coalesce(nullif(current_setting('authz.principal_type', true), ''), 'user') || ' ' || current_setting('authz.user_id', true) END;
BEGIN
  BEGIN
    v_lines := (SELECT string_agg(l, E'\n') FROM authz_gen."ms.users:update:why"(p_row) l);
  EXCEPTION WHEN OTHERS THEN
    v_lines := 'no explanation: ' || SQLERRM;
  END;
  RAISE EXCEPTION USING ERRCODE = 'insufficient_privilege', MESSAGE = 'permission denied: ' || v_who || ' may not ' || 'update this row of ms.users to these values',
    DETAIL = v_lines, SCHEMA = 'ms', TABLE = 'users', CONSTRAINT = 'authz_update',
    HINT = 'the update rule must hold on the row after the change too (Postgres checks both) (rowstile help AZ709)';
END $f$;

CREATE OR REPLACE FUNCTION authz_gen."ms.users:rules:explain"(p_command text, p_id text, p_row jsonb) RETURNS text[]
LANGUAGE plpgsql STABLE SET search_path FROM CURRENT AS $f$
DECLARE r_old "ms"."users"; r_new "ms"."users";
BEGIN
  IF p_command = 'insert' THEN
    RETURN ARRAY['no   there is no insert rule for ms.users: nobody may insert its rows'];
  END IF;
  IF p_id IS NULL THEN
    RAISE EXCEPTION 'which row? authz.explain_rule(%, %, id)', 'ms.users', p_command USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ710';
  END IF;
  SELECT x.* INTO r_old FROM "ms"."users" x WHERE x."id" = p_id::uuid;
  IF NOT FOUND THEN
    RETURN NULL;          -- not there, or the signed-in user can't see it
  END IF;
  IF p_command = 'delete' THEN
    RETURN ARRAY['no   there is no delete rule for ms.users: nobody may delete its rows'];
  END IF;
  r_new := jsonb_populate_record(r_old, coalesce(p_row, '{}'));
  RETURN ARRAY(SELECT * FROM authz_gen."ms.users:update:why"(r_old)) || CASE WHEN p_row IS NULL THEN '{}'::text[] ELSE ARRAY['after the change:'] || ARRAY(SELECT '  ' || l FROM authz_gen."ms.users:update:why"(r_new) l) END;
END $f$;

