  USING (((SELECT authz_int.scope_cmd('ms.users', 'update')) AND coalesce("users"."id" = (SELECT authz.uid()), false)))
  WITH CHECK (((SELECT authz_int.scope_cmd('ms.users', 'update')) AND coalesce("users"."id" = (SELECT authz.uid()), false))
    OR authz_gen."ms.users:update:refuse"(ROW("users".*)::"ms"."users"));
COMMENT ON POLICY "authz_update" ON "ms"."users" IS 'rowstile';

